def calculate_black_area_doubled(A: int, B: int, C: int, D: int) -> int:
    """Calculate twice the black area in the wallpaper rectangle."""
    # Each integer unit square is either uniformly colored or bisected by a
    # diagonal. The doubled contribution therefore depends only on the square's
    # coordinates modulo four.
    def count_residue(start: int, stop: int, residue: int) -> int:
        return (stop - 1 - residue) // 4 - (start - 1 - residue) // 4

    xs = [count_residue(A, C, r) for r in range(4)]
    ys = [count_residue(B, D, r) for r in range(4)]

    total = 0
    for i in range(4):
        for j in range(4):
            if (i + j) % 2:
                weight = 1
            else:
                color_parity = i + j // 2 + (i + j) // 2
                weight = 2 if color_parity % 2 == 0 else 0
            total += xs[i] * ys[j] * weight
    return total

