from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on the coordinate plane."""
    sx, sy = S_x // K, S_y // K
    tx, ty = T_x // K, T_y // K

    def horizontal(i, j):
        return i % 2 == j % 2

    def strip_index(x, y, h):
        return y % K if h else x % K

    sh, th = horizontal(sx, sy), horizontal(tx, ty)
    sk, tk = strip_index(S_x, S_y, sh), strip_index(T_x, T_y, th)
    start, goal = (sx, sy, sk), (tx, ty, tk)
    dx, dy = abs(tx - sx), abs(ty - sy)
    span = dx + dy

    if span > 120:
        # A no-realignment route alternates its x/y block crossings. Crossing
        # counts must match each signed displacement's parity and differ by
        # at most one. Include balancing excursions around the larger axis
        # count, then account for endpoint strip alignment when the first or
        # last axis is perpendicular to the endpoint tile's long direction.
        start_free_axis = 0 if sh else 1
        goal_free_axis = 0 if th else 1
        start_penalty = min(sk, K - 1 - sk)
        goal_penalty = min(tk, K - 1 - tk)
        best = 10**100
        limit = max(dx, dy) + 4
        for nx in range(dx, limit + 1, 2):
            for ny in range(dy, limit + 1, 2):
                if abs(nx - ny) > 1:
                    continue
                if nx == ny:
                    patterns = ((0, 1), (1, 0))
                elif nx > ny:
                    patterns = ((0, 0),)
                else:
                    patterns = ((1, 1),)
                for first, last in patterns:
                    cost = nx + ny
                    if first != start_free_axis:
                        cost += start_penalty
                    if last != goal_free_axis:
                        cost += goal_penalty
                    best = min(best, cost)
        return best

    # For nearby blocks, run Dijkstra on the exact strip graph. Strip offsets
    # are compressed to endpoint and boundary offsets, where the edge-cost
    # functions change slope.
    indices = sorted({0, K - 1, sk, tk})
    index_values = tuple(indices)

    def is_h(node):
        return horizontal(node[0], node[1])

    def edges(node):
        i, j, k = node
        h = is_h(node)
        for kk in index_values:
            if kk != k:
                yield (i, j, kk), abs(kk - k)
        if h:
            yield (i + 1, j, 0), 1
            yield (i - 1, j, K - 1), 1
            if k == K - 1:
                for kk in index_values:
                    yield (i, j + 1, kk), 1
            if k == 0:
                for kk in index_values:
                    yield (i, j - 1, kk), 1
        else:
            yield (i, j + 1, 0), 1
            yield (i, j - 1, K - 1), 1
            if k == K - 1:
                for kk in index_values:
                    yield (i + 1, j, kk), 1
            if k == 0:
                for kk in index_values:
                    yield (i - 1, j, kk), 1

    distances = {start: 0}
    queue = [(0, start)]
    while queue:
        distance, node = heappop(queue)
        if distance != distances[node]:
            continue
        if node == goal:
            return distance
        for neighbor, cost in edges(node):
            candidate = distance + cost
            if candidate < distances.get(neighbor, 10**100):
                distances[neighbor] = candidate
                heappush(queue, (candidate, neighbor))
    return 0

