from typing import List


def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    """Find a non-empty subsequence with alternating sum k and maximum product <= limit."""
    # For each (alternating sum, next sign), retain every attainable in-limit
    # product: a smaller product can still lead to a better result after a
    # later multiplication. Over-limit products only matter if a zero later
    # resets their product to zero, so track their existence separately.
    dp = {}
    over = set()

    for x in nums:
        next_dp = {state: products.copy() for state, products in dp.items()}
        next_over = set(over)

        # A new subsequence may begin at this element (its index in the
        # subsequence is even, so it contributes positively).
        if x <= limit:
            next_dp.setdefault((x, 1), set()).add(x)
        else:
            next_over.add((x, 1))

        for (total, length_parity), products in dp.items():
            # Appending contributes with a minus sign after an odd-length
            # prefix and with a plus sign after an even-length prefix.
            new_total = total - x if length_parity else total + x
            new_parity = 1 - length_parity
            target = (new_total, new_parity)
            out = next_dp.setdefault(target, set())
            for product in products:
                candidate = product * x
                if candidate <= limit:
                    out.add(candidate)
                else:
                    next_over.add(target)

        for total, length_parity in over:
            new_total = total - x if length_parity else total + x
            target = (new_total, 1 - length_parity)
            if x == 0:
                next_dp.setdefault(target, set()).add(0)
            else:
                next_over.add(target)

        dp, over = next_dp, next_over

    answer = -1
    for (total, _), products in dp.items():
        if total == k and products:
            answer = max(answer, max(products))
    return answer

