from math import isqrt


def count_power_representations(n: int) -> int:
    """Count integers x in [1, n] expressible as a^b for a >= 1 and b >= 2."""
    if n < 1:
        return 0

    count = isqrt(n)

    def integer_root(value: int, exponent: int) -> int:
        """Return floor(value ** (1 / exponent)) using integer arithmetic."""
        lo = 1
        hi = 1 << ((value.bit_length() + exponent - 1) // exponent)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if mid ** exponent <= value:
                lo = mid
            else:
                hi = mid - 1
        return lo

    # Enumerate all powers with exponent >= 3. Squares are already counted;
    # the set removes overlaps among different bases and exponents.
    extra = set()
    for exponent in range(3, n.bit_length()):
        max_base = integer_root(n, exponent)
        for base in range(2, max_base + 1):
            value = base ** exponent
            root = isqrt(value)
            if root * root != value:
                extra.add(value)

    return count + len(extra)

