from functools import lru_cache
from typing import List


def determine_winner(n: int, a: List[int]) -> str:
    """Determine the winner under optimal play.

    The state consists of the indices not yet selected and the number of
    remaining moves available on already-selected indices.
    """
    if n == 1:
        return "Fennec"

    # At most n indices can still be selected. Once the repeat-move supply
    # exceeds this horizon, preserve its parity at the saturation boundary.
    cap = 2 * n + 2

    def capped(value: int) -> int:
        if value <= cap:
            return value
        return cap if value % 2 == 0 else cap - 1

    @lru_cache(maxsize=None)
    def winning(mask: int, passes: int) -> bool:
        if mask.bit_count() == 1:
            return True

        if passes and not winning(mask, passes - 1):
            return True

        bits = mask
        while bits:
            bit = bits & -bits
            i = bit.bit_length() - 1
            bits -= bit
            next_passes = capped(passes + a[i] - 1)
            if not winning(mask ^ bit, next_passes):
                return True
        return False

    return "Fennec" if winning((1 << n) - 1, 0) else "Snuke"

