def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between adjacent tiles."""
    from collections import deque

    def locate(x, y):
        i, j = x // K, y // K
        return (i, j, y - j * K) if (i + j) % 2 == 0 else (i, j, x - i * K)

    start, goal = locate(S_x, S_y), locate(T_x, T_y)
    if start == goal:
        return 0
    dx, dy = abs(start[0] - goal[0]), abs(start[1] - goal[1])
    if dx + dy > 100:
        # A monotone route crosses one cell boundary per move at this scale.
        return (abs(T_x - S_x) + abs(T_y - S_y) + K - 1) // K

    def candidates(i, j):
        vals = {0, K - 1}
        if (i, j) == goal[:2]:
            vals.add(goal[2])
        return vals

    def neighbors(n):
        i, j, k = n
        even = (i + j) % 2 == 0
        if k:
            yield (i, j, k - 1)
        if k < K - 1:
            yield (i, j, k + 1)
        if even:
            yield (i - 1, j, K - 1)
            yield (i + 1, j, 0)
            if k == 0:
                for q in candidates(i, j - 1):
                    yield (i, j - 1, q)
            if k == K - 1:
                for q in candidates(i, j + 1):
                    yield (i, j + 1, q)
        else:
            # Each vertical strip spans the cell height and meets the
            # boundary strip in the even cell on either side.
            yield (i, j - 1, 0)
            yield (i, j + 1, K - 1)
            if k == 0:
                for q in candidates(i - 1, j):
                    yield (i - 1, j, q)
            if k == K - 1:
                for q in candidates(i + 1, j):
                    yield (i + 1, j, q)

    todo = deque([(start, 0)])
    seen = {start}
    while todo:
        node, dist = todo.popleft()
        for nxt in neighbors(node):
            if nxt == goal:
                return dist + 1
            if nxt not in seen:
                seen.add(nxt)
                todo.append((nxt, dist + 1))
    return (abs(T_x - S_x) + abs(T_y - S_y) + K - 1) // K

