def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count self-avoiding walks of K moves starting at any empty cell."""
    if K < 0:
        return 0
    cells = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == "."]
    if len(cells) <= K:
        return 0

    # Map each usable cell to an index and precompute its grid neighbors.
    index = {cell: i for i, cell in enumerate(cells)}
    neighbors = [[] for _ in cells]
    for i, (r, c) in enumerate(cells):
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            j = index.get((nr, nc))
            if j is not None:
                neighbors[i].append(j)

    total = 0

    def walk(cell: int, visited: int, remaining: int) -> int:
        if remaining == 0:
            return 1
        count = 0
        for nxt in neighbors[cell]:
            bit = 1 << nxt
            if not visited & bit:
                count += walk(nxt, visited | bit, remaining - 1)
        return count

    for start in range(len(cells)):
        total += walk(start, 1 << start, K)
    return total

