MOD = 998244353


def count_polish_sequences(n: int, a: list[int]) -> int:
    """Count Polish sequences of length n lexicographically at most a, modulo 998244353."""
    # A Polish sequence is the preorder sequence of out-degrees of a rooted
    # ordered tree. After a prefix with q pending child slots, a completion
    # with k nodes is a forest of q roots.
    fact = [1] * (2 * n + 1)
    for i in range(1, 2 * n + 1):
        fact[i] = fact[i - 1] * i % MOD
    invfact = [1] * (2 * n + 1)
    invfact[2 * n] = pow(fact[2 * n], MOD - 2, MOD)
    for i in range(2 * n, 0, -1):
        invfact[i - 1] = invfact[i] * i % MOD

    def choose(top: int, bottom: int) -> int:
        if bottom < 0 or top < bottom:
            return 0
        return fact[top] * invfact[bottom] % MOD * invfact[top - bottom] % MOD

    # Number of k-node forests whose number of roots is at least lower.
    # This is [z^k] T^lower/(1-T), where T=z/(1-T).
    def tail(k: int, lower: int) -> int:
        if lower < 0:
            lower = 0
        if lower > k:
            return 0
        if k == 0:
            return 1 if lower == 0 else 0
        top = 2 * k - lower
        return (
            lower * choose(top, k - lower)
            + choose(top, k - lower - 1)
        ) % MOD * pow(k, MOD - 2, MOD) % MOD

    answer = 0
    slots = 1
    for i, bound in enumerate(a):
        remaining = n - i - 1

        min_degree = max(0, 1 - slots)
        max_degree = min(bound - 1, remaining - slots + 1)
        if min_degree <= max_degree:
            low_roots = slots - 1 + min_degree
            high_roots = slots - 1 + max_degree
            answer += tail(remaining, low_roots) - tail(remaining, high_roots + 1)
            answer %= MOD

        slots += bound - 1
        if slots < 0 or slots > remaining or (slots == 0 and remaining > 0):
            return answer

    if slots == 0:
        answer = (answer + 1) % MOD
    return answer

