def can_color_all_points(n: int, k: int) -> bool:
    """ Alice and Bob are on a circle with n equally spaced points numbered 0 to n-1.
    Alice is at point 0, Bob is at point k. Initially all points are white.

    Starting with Alice, they alternately color one white point black, with the constraint
    that after coloring, the pattern must be symmetric with respect to the line connecting
    the player to the center of the circle.

    Both players cooperate to maximize the total number of colored points.

    Args:
        n: Number of points on the circle (2 <= n <= 2*10^5)
        k: Bob's position (1 <= k <= n-1)

    Returns:
        True if all points can be colored black, False otherwise

    >>> can_color_all_points(6, 2)
    True
    >>> can_color_all_points(6, 3)
    False
    >>> can_color_all_points(6, 1)
    True
    """
    def reflect(point: int, axis: int) -> int:
        return (2 * axis - point) % n

    def fixed_points(axis: int):
        if n % 2:
            return (axis,)
        return (axis, (axis + n // 2) % n)

    # For an involution, a set is symmetric exactly when it contains either
    # both or neither endpoint of every non-fixed reflection pair. Keep the
    # number of split pairs and their uncolored endpoints incrementally.
    def add_point(colored, point, c0, x0, ck, xk):
        colored[point] = 1
        other = reflect(point, 0)
        if other != point:
            if colored[other]:
                c0 -= 1
                x0 ^= point
            else:
                c0 += 1
                x0 ^= other
        other = reflect(point, k)
        if other != point:
            if colored[other]:
                ck -= 1
                xk ^= point
            else:
                ck += 1
                xk ^= other
        return c0, x0, ck, xk

    # The first move is by Alice and must be a fixed point of her reflection.
    todo = []
    for first in fixed_points(0):
        colored = bytearray(n)
        c0, x0, ck, xk = add_point(colored, first, 0, 0, 0, 0)
        todo.append((colored, 1, c0, x0, ck, xk))

    while todo:
        colored, moves, c0, x0, ck, xk = todo.pop()
        if moves == n:
            return True

        axis = k if moves % 2 else 0  # next player (move moves + 1)
        if axis == 0:
            count, outside = c0, x0
        else:
            count, outside = ck, xk

        if count == 1:
            choices = (outside,)
        elif count == 0:
            choices = tuple(p for p in fixed_points(axis) if not colored[p])
        else:
            continue

        for point in choices:
            # Every valid choice is white; the xor tracks only a missing
            # endpoint, while fixed points are selected explicitly.
            if colored[point]:
                continue
            if len(choices) == 1:
                next_colored = colored
            else:
                next_colored = colored.copy()
            nc0, nx0, nck, nxk = add_point(
                next_colored, point, c0, x0, ck, xk
            )
            todo.append((next_colored, moves + 1, nc0, nx0, nck, nxk))

    return False

