def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """Count integers in [start, finish] ending in s with every digit <= limit."""
    if start > finish or any(int(ch) > limit for ch in s):
        return 0

    suffix_value = int(s)

    def count_at_most(bound: int) -> int:
        if bound < suffix_value:
            return 0

        bound_text = str(bound)
        suffix_len = len(s)
        if len(bound_text) < suffix_len:
            return 0

        # The suffix alone is a valid integer, regardless of whether the
        # bound has additional digits.
        total = 1
        prefix_len = len(bound_text) - suffix_len

        # Count all valid numbers with a nonempty prefix shorter than the
        # bound's prefix. The first digit must be nonzero.
        for length in range(1, prefix_len):
            total += limit * (limit + 1) ** (length - 1)

        # Count valid prefixes of this length that are strictly below the
        # bound prefix. Include an equal prefix only when the suffix also
        # fits within the bound.
        if prefix_len:
            prefix_bound = bound_text[:prefix_len]
            for i, ch in enumerate(prefix_bound):
                digit = int(ch)
                low = 1 if i == 0 else 0
                choices = max(0, min(limit, digit - 1) - low + 1)
                remaining = prefix_len - i - 1
                total += choices * (limit + 1) ** remaining
                if digit < low or digit > limit:
                    break
            else:
                if s <= bound_text[prefix_len:]:
                    total += 1

        return total

    return count_at_most(finish) - count_at_most(start - 1)

