def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Takahashi and Aoki play optimally, each playing a card and optionally
    taking a strictly smaller card from the table.
    """
    values = sorted(set(takahashi_cards) | set(aoki_cards) | set(table_cards))
    index = {value: i for i, value in enumerate(values)}

    def counts(cards: List[int]) -> Tuple[int, ...]:
        result = [0] * len(values)
        for value in cards:
            result[index[value]] += 1
        return tuple(result)

    @lru_cache(maxsize=None)
    def win(turn: int, ht: Tuple[int, ...], ha: Tuple[int, ...], table: Tuple[int, ...]) -> bool:
        hand = ht if turn == 0 else ha
        if not any(hand):
            return False

        for i, count in enumerate(hand):
            if not count:
                continue

            # Play one card, with no card taken from the table.
            next_hand = list(hand)
            next_hand[i] -= 1
            next_table = list(table)
            next_table[i] += 1
            if turn == 0:
                nt, na = tuple(next_hand), ha
            else:
                nt, na = ht, tuple(next_hand)
            if not win(1 - turn, nt, na, tuple(next_table)):
                return True

            # Alternatively take one table card strictly smaller than the
            # card just played.
            for j in range(i):
                if next_table[j] == 0:
                    continue
                taken_hand = next_hand.copy()
                taken_hand[j] += 1
                taken_table = next_table.copy()
                taken_table[j] -= 1
                if turn == 0:
                    nt, na = tuple(taken_hand), ha
                else:
                    nt, na = ht, tuple(taken_hand)
                if not win(1 - turn, nt, na, tuple(taken_table)):
                    return True

        return False

    return "Takahashi" if win(0, counts(takahashi_cards), counts(aoki_cards), counts(table_cards)) else "Aoki"

