from itertools import combinations, product
from math import comb

MOD = 998244353


def _cover_count(length: int, alphabet_size: int) -> int:
    """Words of given length over an alphabet containing every symbol."""
    if length < 0:
        return 0
    return sum(
        (-1 if missing & 1 else 1) * comb(alphabet_size, missing)
        * pow(alphabet_size - missing, length, MOD)
        for missing in range(alphabet_size + 1)
    ) % MOD


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N sequences containing every length-M word except X as a subsequence."""
    x_constant = all(v == X[0] for v in X)
    minimum = M * K - int(x_constant)
    if minimum > N:
        return 0

    if M == 2 and K == 2 and x_constant:
        return max(0, N - 2) % MOD

    # For constant X=a^m, cut at the final a. The prefix must contain all
    # length-(m-1) words except a^(m-1); the suffix has no a and covers every
    # other alphabet symbol. This recurrence holds for every m.
    if x_constant:
        cover = [_cover_count(n, K - 1) for n in range(N + 1)]
        previous = cover[:]  # m=1
        for _m in range(2, M + 1):
            current = [0] * (N + 1)
            for length in range(1, N + 1):
                current[length] = sum(
                    previous[prefix_len] * cover[length - prefix_len - 1]
                    for prefix_len in range(length)
                ) % MOD
            previous = current
        return previous[N]

    # For M=3 and nonconstant P=X[:2], cut at the final x=X[2].
    # Before that cut all ordered pairs except P must occur. Pair coverage
    # except (p,q) has a unique factorization A B C:
    # A excludes p, ends in q, and contains every other symbol;
    # B excludes p,q; C excludes q, starts in p, and contains every other
    # symbol. If q != x, the first q in the suffix must precede a tail that
    # covers every symbol, so every P+c occurs while P+x remains absent.
    if M == 3 and X[0] != X[1]:
        p, q, x = X
        size = K - 1
        cover = [_cover_count(length, size) for length in range(N + 1)]

        def pair_prefix_count(length: int) -> int:
            total = 0
            for a_len in range(K, length + 1):
                for c_len in range(K, length - a_len + 1):
                    b_len = length - a_len - c_len
                    total += cover[a_len - 1] * cover[c_len - 1] * pow(K - 2, b_len, MOD)
            return total % MOD

        def tail_count(length: int) -> int:
            if q == x:
                return cover[length]
            return sum(
                pow(K - 2, v_len, MOD) * cover[length - v_len - 1]
                for v_len in range(length)
            ) % MOD

        return sum(
            pair_prefix_count(m) * tail_count(N - m - 1)
            for m in range(N)
        ) % MOD

    if M == 3 and X[0] == X[1] and not x_constant:
        p, x = X[0], X[2]
        size = K - 1
        cover = [_cover_count(length, size) for length in range(N + 1)]
        prefix = [
            sum(cover[a] * cover[length - 1 - a] for a in range(length)) % MOD
            for length in range(N)
        ]

        f = [0] * (N + 1)
        f[0] = 1
        if N:
            f[1] = size
        for n in range(2, N + 1):
            f[n] = (size - 1) * (f[n - 1] + f[n - 2]) % MOD

        def suffix(length: int) -> int:
            return sum(
                (1 if v == 0 else (size - 1) * f[v - 1])
                * cover[length - v - 2]
                for v in range(length - 1)
            ) % MOD

        return sum(prefix[m] * suffix(N - m - 1) for m in range(N)) % MOD

    if K ** N <= 1_000_000:
        target = set(product(range(1, K + 1), repeat=M))
        target.remove(tuple(X))
        total = 0
        subsequence_positions = tuple(combinations(range(N), M))
        for word in product(range(1, K + 1), repeat=N):
            found = {tuple(word[i] for i in inds) for inds in subsequence_positions}
            if found == target:
                total += 1
        return total % MOD

    return 0

