def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """ Given a grid with H rows and W columns consisting of '1', '2', '3', and '?',
    count how many ways we can replace each '?' with '1', '2', or '3' such that
    any two adjacent (edge-sharing) cells contain different digits.

    Return the count modulo 998244353.

    Args:
        H: Number of rows (1 <= H, H * W <= 200)
        W: Number of columns (1 <= W, H * W <= 200)
        grid: List of strings representing the grid, where grid[i] is the i-th row

    Returns:
        The number of valid grid configurations modulo 998244353
    """
    # Work along the longer dimension so the enumerated row profiles are as
    # narrow as possible.
    if W > H:
        H, W = W, H
        grid = [''.join(grid[r][c] for r in range(len(grid))) for c in range(len(grid[0]))]

    # Each state is a horizontally valid assignment to the current row.
    allowed = []
    for row in grid:
        choices = []
        for ch in row:
            if ch == '?':
                choices.append((0, 1, 2))
            else:
                choices.append((int(ch) - 1,))
        allowed.append(choices)

    dp = {}
    def seed(col, prev, row_choices):
        if col == W:
            dp[tuple(prev)] = 1
            return
        for color in row_choices[col]:
            if col == 0 or color != prev[col - 1]:
                prev.append(color)
                seed(col + 1, prev, row_choices)
                prev.pop()

    seed(0, [], allowed[0])

    for r in range(1, H):
        next_dp = {}
        row_choices = allowed[r]
        for prev_row, ways in dp.items():
            cur = []

            def fill(col):
                if col == W:
                    state = tuple(cur)
                    next_dp[state] = (next_dp.get(state, 0) + ways) % MOD
                    return
                for color in row_choices[col]:
                    if color != prev_row[col] and (col == 0 or color != cur[col - 1]):
                        cur.append(color)
                        fill(col + 1)
                        cur.pop()

            fill(0)
        dp = next_dp
        if not dp:
            return 0

    return sum(dp.values()) % MOD

