from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise
    """
    n = len(tiles)
    target_area = h * w
    areas = [a * b for a, b in tiles]
    subset_sums = {0}
    for area in areas:
        subset_sums |= {s + area for s in tuple(subset_sums)}
    if target_area not in subset_sums:
        return False

    full = (1 << w) - 1
    orientations = [tuple(sorted({(a, b), (b, a)})) for a, b in tiles]

    @lru_cache(maxsize=None)
    def search(rows: Tuple[int, ...], remaining: int) -> bool:
        row = col = -1
        for r, bits in enumerate(rows):
            if bits != full:
                row = r
                col = next(c for c in range(w) if not (bits >> c) & 1)
                break
        if row < 0:
            return True

        empty = target_area - sum(bits.bit_count() for bits in rows)
        possible = {0}
        for i, area in enumerate(areas):
            if remaining >> i & 1:
                possible |= {s + area for s in tuple(possible)}
        if empty not in possible:
            return False

        for i in range(n):
            if not (remaining >> i) & 1:
                continue
            for th, tw in orientations[i]:
                # Try every placement of this rectangle that covers the first
                # uncovered cell. Row-major order usually makes its origin the
                # first empty cell, but enumerating origins keeps the exact-cover
                # condition explicit even when the uncovered region has holes.
                for top in range(max(0, row - th + 1), row + 1):
                    for left in range(max(0, col - tw + 1), col + 1):
                        if top + th > h or left + tw > w:
                            continue
                        mask = ((1 << tw) - 1) << left
                        if any(rows[rr] & mask for rr in range(top, top + th)):
                            continue
                        updated = list(rows)
                        for rr in range(top, top + th):
                            updated[rr] |= mask
                        if search(tuple(updated), remaining ^ (1 << i)):
                            return True
        return False

    return search((0,) * h, (1 << n) - 1)

