@lru_cache(maxsize=None)
def _beautiful_nozero_exact(length: int) -> int:
    """Count beautiful numbers with exactly length digits and no zero digits."""
    answer = 0
    for target in range(1, 9 * length + 1):
        # (digit sum, digit product modulo target) -> number of prefixes
        states = {(0, 1 % target): 1}
        for _ in range(length):
            next_states = {}
            for (digit_sum, remainder), count in states.items():
                max_digit = min(9, target - digit_sum)
                for digit in range(1, max_digit + 1):
                    key = (digit_sum + digit, remainder * digit % target)
                    next_states[key] = next_states.get(key, 0) + count
            states = next_states
        answer += states.get((target, 0), 0)
    return answer


@lru_cache(maxsize=None)
def _beautiful_nozero_upto(bound: int) -> int:
    """Count beautiful, zero-free numbers from 1 through bound."""
    if bound <= 0:
        return 0
    digits = tuple(map(int, str(bound)))
    length = len(digits)
    answer = sum(_beautiful_nozero_exact(k) for k in range(1, length))
    for target in range(1, 9 * length + 1):
        # The bool in each key records whether the prefix still equals bound.
        states = {(0, 1 % target, True): 1}
        for pos, limit_digit in enumerate(digits):
            next_states = {}
            for (digit_sum, remainder, tight), count in states.items():
                upper = limit_digit if tight else 9
                for digit in range(1, upper + 1):
                    new_sum = digit_sum + digit
                    if new_sum > target or new_sum + 9 * (length - pos - 1) < target:
                        continue
                    new_tight = tight and digit == limit_digit
                    key = (new_sum, remainder * digit % target, new_tight)
                    next_states[key] = next_states.get(key, 0) + count
            states = next_states
        answer += states.get((target, 0, False), 0)
        answer += states.get((target, 0, True), 0)
    return answer


def count_beautiful_numbers(l: int, r: int) -> int:
    """ Count the number of beautiful numbers in the range [l, r] inclusive.

    A positive integer is called beautiful if the product of its digits is divisible by the sum of its digits.

    Args:
        l: The lower bound of the range (inclusive)
        r: The upper bound of the range (inclusive)

    Returns:
        The count of beautiful numbers in the range [l, r]

    Constraints:
        1 <= l <= r < 10^9

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    def prefix(n: int) -> int:
        if n <= 0:
            return 0
        # Every number containing a zero has digit product zero and is beautiful.
        digits = len(str(n))
        zero_free_total = sum(9 ** k for k in range(1, digits))
        d = tuple(map(int, str(n)))
        count_top = 0
        for pos, bound_digit in enumerate(d):
            for digit in range(1, bound_digit):
                count_top += 9 ** (len(d) - pos - 1)
            if bound_digit == 0:
                break
        else:
            count_top += 1
        zero_free_total += count_top
        return n - zero_free_total + _beautiful_nozero_upto(n)

    return prefix(r) - prefix(l - 1)

