from functools import lru_cache
from math import isqrt


def _make_chunk_counts() -> tuple[int, ...]:
    counts = []
    for value in range(10_000):
        packed = 0
        for digit in f"{value:04d}":
            packed += 1 << (5 * (ord(digit) - 48))
        counts.append(packed)
    return tuple(counts)


_CHUNK_COUNTS = _make_chunk_counts()


@lru_cache(maxsize=None)
def _count_for_signature(n: int, signature: int) -> int:
    total = 0
    for root in range(isqrt(10 ** n - 1) + 1):
        square = root * root
        packed = (
            _CHUNK_COUNTS[square % 10_000]
            + _CHUNK_COUNTS[(square // 10_000) % 10_000]
            + _CHUNK_COUNTS[(square // 100_000_000) % 10_000]
            + _CHUNK_COUNTS[square // 1_000_000_000_000]
            - (16 - n)
        )
        if packed == signature:
            total += 1
    return total


def count_square_permutations(n: int, s: str) -> int:
    """Given a string s of length n consisting of digits, find the number of unique square numbers
    that can be obtained by interpreting any permutation of the digits as a decimal integer.

    Leading zeroes are allowed, and different permutations resulting in the same integer
    are counted only once.
    """
    counts = [0] * 10
    for digit in s:
        counts[ord(digit) - 48] += 1
    signature = sum(count << (5 * digit) for digit, count in enumerate(counts))
    return _count_for_signature(n, signature)
